return items;

const inputData = $input.all();
if (!inputData || inputData.length === 0) return [];

const cfg = inputData[0].json;
let raw = cfg.body || cfg;
if (Array.isArray(raw)) raw = raw[0] || {};

// 深度探测所有可能的搜索结果路径
const res = [
  ...(raw.web?.results || []),
  ...(raw.news?.results || []),
  ...(raw.videos?.results || []),
  ...(raw.results || []),
  ...(raw.mixed?.main?.filter(i => i.type === 'web').map(i => raw.web?.results?.[i.index]).filter(Boolean) || [])
];

function normalizeUrl(u) {
  if (!u) return '';
  try {
    const url = new URL(u);
    url.hash = '';
    ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','gclid','fbclid'].forEach(k => url.searchParams.delete(k));
    url.search = url.searchParams.toString() ? '?' + url.searchParams.toString() : '';
    return url.toString();
  } catch (e) {
    return u;
  }
}

const seen = new Set();
const out = [];
for (const r of res) {
  if (!r || !r.url) continue;
  const url = normalizeUrl(r.url);
  if (!url || seen.has(url)) continue;
  seen.add(url);

  out.push({
    title: r.title || 'Untitled',
    url,
    description: r.description || r.snippet || '',
    page_age: r.page_age || r.age || null,
    source: r.profile?.name || r.source || null,
    query: cfg.query,
    llamaBaseUrl: cfg.llamaBaseUrl,
    llamaModel: cfg.llamaModel,
    feishuWebhookUrl: cfg.feishuWebhookUrl,
    finalCount: cfg.finalCount || 5
  });
}

// 必须保证输出不为空，否则工作流会在这里中断
if (out.length === 0) {
  return [{
    json: {
      title: 'No results found',
      url: 'https://api.search.brave.com',
      description: 'Brave Search returned no results for the current query and freshness.',
      query: cfg.query,
      llamaBaseUrl: cfg.llamaBaseUrl,
      llamaModel: cfg.llamaModel,
      feishuWebhookUrl: cfg.feishuWebhookUrl,
      finalCount: cfg.finalCount || 5,
      skipProcessing: true
    }
  }];
}

return out.slice(0, 15).map(j => ({ json: j }));

const input = $input.first().json;

let bodyStr = '';
if (typeof input.body === 'string') {
  bodyStr = input.body;
} else if (input.body && typeof input.body === 'object') {
  bodyStr = JSON.stringify(input.body);
} else if (input.data && typeof input.data === 'string') {
  bodyStr = input.data;
} else if (input.data && typeof input.data === 'object') {
  bodyStr = JSON.stringify(input.data);
}

const status = input.statusCode || 0;

const needFallback = 
  status !== 200 || 
  !bodyStr || 
  bodyStr.length < 800 || 
  bodyStr.includes('_cf_chl_opt') || 
  bodyStr.includes('Cloudflare') || 
  bodyStr.includes('Forbidden') ||
  bodyStr.includes('Just a moment...') ||
  bodyStr.includes('Enable JavaScript') ||
  bodyStr.includes('challenge-platform');

return { 
  needFallback 
};

const splitNode = $node["Split In Batches"].json;
const base = $input.first().json;

let body = base.body || base.data || '';
if (typeof body !== 'string') body = JSON.stringify(body);

return [{
  json: {
    title: splitNode.title || '无标题',
    url: splitNode.url,
    description: splitNode.description,
    source: splitNode.source,
    page_age: splitNode.page_age,
    articleText: body.slice(0, 30000),
    llamaBaseUrl: splitNode.llamaBaseUrl,
    llamaModel: splitNode.llamaModel,
    feishuWebhookUrl: splitNode.feishuWebhookUrl,
    finalCount: splitNode.finalCount
  }
}];

