const data = $getWorkflowStaticData('global');
const resp = $input.first().json;

const targetCount = Number($node['Init Run Config'].json.finalCount || 5);
const base = $node['Select Article Text'].json;

if (!Array.isArray(data.items)) data.items = [];
if (typeof data.sent !== 'boolean') data.sent = false;

let translation = resp?.choices?.[0]?.message?.content || '';
if (typeof translation !== 'string') translation = JSON.stringify(translation || '');
translation = translation.trim();

if (!data.sent && translation) {
  if (data.items.length < 50 && data.items.length < targetCount) {
    data.items.push({
      title: base.title || '无标题',
      url: base.url,
      source: base.source || null,
      page_age: base.page_age || null,
      translation
    });
  }
}

const currentCount = data.items.length;
const reachedTarget = currentCount >= targetCount;

if (reachedTarget) data.sent = true;

return [{ json: { reachedTarget, currentCount, targetCount, sent: data.sent } }];

const data = $getWorkflowStaticData('global');
const sent = Boolean(data.sent);
const itemsCount = Array.isArray(data.items) ? data.items.length : 0;
return [{ json: { shouldSend: !sent && itemsCount > 0 } }];

const data = $getWorkflowStaticData('global');
const targetCount = Number($node['Init Run Config'].json.finalCount || 5);
const itemsArr = (data.items || []).slice(0, targetCount);

if (!itemsArr.length) {
  return [{ json: { text: '今日未检索到合格的 AI×制造/钢铁 资讯（过去 24 小时）。' } }];
}

const header = '【AI×制造/钢铁资讯】过去24小时精选 ' + itemsArr.length + ' 条';

function safe(s) {
  return (s || '').toString().trim();
}

function fmtMeta(it) {
  const src = safe(it.source);
  const age = safe(it.page_age);
  const meta = [];
  if (src) meta.push('来源：' + src);
  if (age) meta.push('时间：' + age);
  return meta.length ? meta.join('｜') : '';
}

function clip(s, maxLen) {
  const t = safe(s);
  if (!t) return '';
  if (t.length <= maxLen) return t;
  return t.slice(0, maxLen) + '\n\n（内容过长已截断，详见原文链接）';
}

const body = itemsArr.map((it, idx) => {
  const title = safe(it.title) || '无标题';
  const meta = fmtMeta(it);
  const url = safe(it.url);
  const translation = clip(it.translation, 6000);

  const lines = [];
  lines.push('\n\n---\n\n# ' + (idx + 1) + '｜' + title);
  if (meta) lines.push(meta);
  if (url) lines.push('链接：' + url);
  if (translation) lines.push('\n' + translation);
  return lines.join('\n');
}).join('');

return [{ json: { text: header + body } }];

